const ExploreMap: React.FC = () => {
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  const handleMouseMove = (e: React.MouseEvent) => {
    setMousePos({ x: e.clientX, y: e.clientY });
  };

  const targets = BUBBLES.map(b => ({
    x: (b.x / 100) * (containerRef.current?.clientWidth || window.innerWidth),
    y: (b.y / 100) * (containerRef.current?.clientHeight || window.innerHeight)
  }));

  return (
    <div 
      ref={containerRef}
      className="relative w-full h-[85vh] overflow-hidden bg-[#050505] rounded-3xl mt-24 border border-white/5 mx-auto max-w-7xl cursor-crosshair"
      onMouseMove={handleMouseMove}
