          <div key={i} className="border-r border-white/20 h-full flex items-end p-4">
            <span className="text-[10px] uppercase">Q{Math.floor(i/3)+1}</span>
          </div>
        ))}
      </div>

      <InfographicLines origin={mousePos} targets={targets} active={!!hoveredId} />

      {BUBBLES.map((bubble) => (
        <div
          key={bubble.id}
          className={`absolute transition-all duration-700 bubble-hover cursor-pointer float-anim`}
          style={{
            left: `${bubble.x}%`,
            top: `${bubble.y}%`,
            width: `${bubble.size}px`,
            height: `${bubble.size}px`,
            zIndex: hoveredId === bubble.id ? 20 : 10,
            animationDelay: `${parseInt(bubble.id) * 0.5}s`
          }}
          onMouseEnter={() => setHoveredId(bubble.id)}
          onMouseLeave={() => setHoveredId(null)}
        >
          <div className={`w-full h-full rounded-full glass border p-4 flex flex-col items-center justify-center text-center group ${CATEGORY_COLORS[bubble.category]}`}>
